passthroughCss:
@import url("fonts.css");

@font-face {
  font-family: "Inter";
  src: url("inter.woff2") format("woff2");
}

:root {
  --brand: #123456;
}

*, ::before, ::after {
  box-sizing: border-box;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-color-scheme: dark) {
  :root {
    --brand: #abcdef;
  }
}
